package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"log/slog"
	"time"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/enrich"
	"github.com/mellifera/mellifera/internal/module"
	"github.com/mellifera/mellifera/internal/recs"
	"github.com/mellifera/mellifera/internal/store"
)

// recsInterval is the learning task's ticker period (recommendation-sorting
// D5), locked like sweepInterval: a rule constant, not a knob.
const recsInterval = 60 * time.Second

// recsWake is the recs janitor task's completion wake (recommendation-sorting
// D5): a completion insert pokes it so the next learning pass runs at once
// instead of waiting out the tick. Capacity 1 coalesces a completion burst
// into one pending pass. The channel is NEVER closed (the wake precedent
// carries no close — main.go's queue-notify targets): the janitor loop exits
// on ctx.Done, and a send racing shutdown must not panic.
var recsWake = make(chan struct{}, 1)

// notifyRecs pokes the recs wake — the seam the watch detector calls on every
// completion insert. The design's select-on-ctx send shape degenerates here
// to a default-guarded send over the capacity-1 channel: a full buffer means
// a pass is already pending and covers this completion, so blocking until
// ctx.Done would stall the progress path for no learning effect — and with
// no close there is nothing to panic on.
func notifyRecs() {
	select {
	case recsWake <- struct{}{}:
	default:
	}
}

// newRecsSweep builds the janitor registry's recs task (recommendation-
// sorting D5): one pass selects every completed watch whose applied_at is
// still NULL (the derived queue — no jobs table), resolves each entity's
// tags through the enrich resolver, accumulates +1 per tag occurrence across
// the pass, and commits the weights and the applied_at stamp in ONE
// ApplyTagWeights transaction. Rows arrive ordered by completed_at, so a
// pass consumes a contiguous prefix: the first row whose resolution fails
// ends the pass (its tags are unknown — stamping past it would consume a
// watch unlearned), and the stamp cutoff is the last resolved row's
// completed_at, so a watch landing mid-pass stays unapplied for the next
// pass (restart-safe). Every failure is log-and-skip: learning is never
// load-bearing.
func newRecsSweep(st *store.Store, reg *module.Registry) func(context.Context) {
	return func(ctx context.Context) {
		itemIDs, libraryIDs, seriesPaths, completed, err := st.ListUnappliedWatched(ctx)
		if err != nil {
			slog.Warn("recs: list unapplied watched failed", "error", err)
			return
		}
		var tags []string
		applied := 0
		for i := range itemIDs {
			rowTags, err := resolveWatchTags(ctx, st, reg, itemIDs[i], libraryIDs[i], seriesPaths[i])
			if err != nil {
				slog.Warn("recs: tag resolution failed; pass stops before the row",
					"item", itemIDs[i], "error", err)
				break
			}
			for _, t := range rowTags {
				tags = append(tags, recs.NormalizeTag(t))
			}
			applied = i + 1
		}
		if applied == 0 {
			return
		}
		if err := st.ApplyTagWeights(ctx, tags, completed[applied-1]); err != nil {
			slog.Warn("recs: apply tag weights failed", "error", err)
		}
	}
}

// resolveWatchTags resolves ONE watched row's tags (recommendation-sorting
// D1): an episode's tags live on its SERIES document — the watched row's
// (library_id, series_relative_path) is the join — and a film/tv item's tags
// on its own document. The chain resolves per the entity's module and library
// through ResolveGates. A vanished entity or an unresolvable module is honest
// absence (no tags — the row is consumed without weights), not a failure: a
// permanently unresolvable row must never starve the queue.
func resolveWatchTags(ctx context.Context, st *store.Store, reg *module.Registry, itemID string, libraryID int64, seriesPath string) ([]string, error) {
	moduleID, doc, err := watchEntityDoc(ctx, st, itemID, libraryID, seriesPath)
	if err != nil || doc == nil {
		return nil, err // nil document = vanished entity, already folded to absence
	}
	mod, err := reg.Get(moduleID)
	if err != nil {
		return nil, nil // unknown module — no chain, no carrier
	}
	prefs, err := st.ListMetadataSourcePrefs(ctx, moduleID, []int64{libraryID})
	if err != nil {
		return nil, err
	}
	return enrich.ResolveGenres(doc, enrich.ResolveGates(mod, prefs, libraryID)), nil
}

// watchEntityDoc loads the winning document for one watched row: the series
// row for an episode (seriesPath non-empty), the item row for a film/tv item.
// A vanished row (deleted since the watch) folds to a nil document — honest
// absence; every other read failure returns as an error.
func watchEntityDoc(ctx context.Context, st *store.Store, itemID string, libraryID int64, seriesPath string) (string, json.RawMessage, error) {
	if seriesPath == "" {
		it, err := st.GetItem(ctx, itemID, access.System())
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return "", nil, nil
			}
			return "", nil, err
		}
		return it.ModuleID, it.Document, nil
	}
	sr, err := st.GetSeriesByPath(ctx, libraryID, seriesPath, access.System())
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return "", nil, nil
		}
		return "", nil, err
	}
	return sr.ModuleID, sr.Document, nil
}
